CREATE OR REPLACE FUNCTION public.enforce_team_member_caps() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_plan text;v_addon int;v_owner uuid;v_invitee_email text;v_core int;v_ext int;v_cap int;v_type text;v_classification text;v_has_approval boolean; BEGIN
SELECT plan,addon_seats,billing_owner_user_id INTO v_plan,v_addon,v_owner FROM public.teams WHERE id=NEW.team_id;
IF v_plan='beta' OR NEW.role='owner'::team_role OR v_owner IS NULL OR NEW.user_id=v_owner THEN NEW.member_type:='core'; RETURN NEW; END IF;
SELECT email INTO v_invitee_email FROM auth.users WHERE id=NEW.user_id;v_classification:=public.classify_invitee(NEW.team_id,v_invitee_email);
IF v_classification='requires_explicit_choice' THEN IF NEW.member_type IS NULL THEN RAISE EXCEPTION 'member_type_required'; END IF;v_type:=NEW.member_type;ELSE v_type:=v_classification; END IF;
SELECT count(*) FILTER(WHERE member_type='core'),count(*) FILTER(WHERE member_type='external') INTO v_core,v_ext FROM public.team_members WHERE team_id=NEW.team_id;
IF v_type='core' THEN v_cap:=public.plan_core_cap(v_plan,v_addon); IF v_core+1>v_cap THEN RAISE EXCEPTION 'seat_cap_core'; END IF;
ELSE IF NOT public.plan_allows_externals(v_plan) THEN RAISE EXCEPTION 'plan_no_externals';END IF;
SELECT EXISTS(SELECT 1 FROM public.team_external_approvals WHERE team_id=NEW.team_id AND lower(invitee_email::text)=lower(v_invitee_email) AND status='approved') INTO v_has_approval;
IF NOT v_has_approval THEN RAISE EXCEPTION 'external_not_approved';END IF;IF v_ext+1>v_core*5 THEN RAISE EXCEPTION 'seat_cap_external';END IF;END IF;NEW.member_type:=v_type;RETURN NEW;END $$;
ALTER POLICY "Projects: team members create" ON public.projects WITH CHECK(auth.uid()=created_by AND public.is_team_project_manager(auth.uid(),team_id));
ALTER POLICY "Areas: members read" ON public.areas USING(public.is_project_member(auth.uid(),project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(project_id)));
ALTER POLICY "GuestNotes: members read" ON public.guest_notes USING(public.is_project_reader(auth.uid(),project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(project_id)));
ALTER POLICY "Exports: members read" ON public.project_exports USING(public.is_project_reader(auth.uid(),project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(project_id)));
ALTER POLICY "Activity: members read" ON public.activity_events USING(public.is_project_reader(auth.uid(),project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(project_id)));
ALTER POLICY "Albums: members read" ON public.albums USING(public.is_project_reader(auth.uid(),project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(project_id)));
ALTER POLICY "Share: readers read" ON public.share_links USING(public.is_project_reader(auth.uid(),project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(project_id)));
ALTER POLICY "Profiles: read project co-members" ON public.profiles USING(EXISTS(SELECT 1 FROM public.project_members pm WHERE pm.user_id=profiles.id AND (public.is_project_member(auth.uid(),pm.project_id) OR public.is_team_project_manager(auth.uid(),public.project_team_id(pm.project_id)))));
CREATE OR REPLACE FUNCTION public.my_accessible_projects() RETURNS TABLE(id uuid,name text,description text,template public.project_template,created_at timestamptz,color text,event_date date,event_location text,overall_status public.project_status,event_type text,client_name text,archived_at timestamptz,folder_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT p.id,p.name,p.description,p.template,p.created_at,p.color,p.event_date,p.event_location,p.overall_status,p.event_type,p.client_name,p.archived_at,(SELECT upf.folder_id FROM public.user_project_folders upf WHERE upf.user_id=auth.uid() AND upf.project_id=p.id) FROM public.projects p WHERE auth.uid() IS NOT NULL AND (public.is_project_member(auth.uid(),p.id) OR public.is_team_project_manager(auth.uid(),p.team_id)) ORDER BY p.created_at DESC $$;
CREATE OR REPLACE FUNCTION public.can_read_photo_object(_user uuid,_name text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid;BEGIN IF _user IS NULL OR _name IS NULL THEN RETURN false;END IF;BEGIN pid:=split_part(_name,'/',1)::uuid;EXCEPTION WHEN OTHERS THEN RETURN false;END;
IF public.is_project_reader(_user,pid) OR public.is_team_project_manager(_user,public.project_team_id(pid)) THEN RETURN true;END IF;
RETURN public.is_project_crew(_user,pid) AND EXISTS(SELECT 1 FROM public.photos WHERE project_id=pid AND (storage_path=_name OR report_path=_name) AND uploaded_by=_user);END $$;
CREATE OR REPLACE FUNCTION public.can_read_export_asset(_user uuid,_name text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE prefix text:=split_part(_name,'/',1);second text:=split_part(_name,'/',2);pid uuid;tid uuid;BEGIN
IF prefix='logos' THEN BEGIN tid:=second::uuid;EXCEPTION WHEN OTHERS THEN RETURN false;END;RETURN public.is_team_member(_user,tid);
ELSIF prefix='covers' THEN BEGIN pid:=second::uuid;EXCEPTION WHEN OTHERS THEN RETURN false;END;RETURN public.is_project_reader(_user,pid) OR public.is_team_project_manager(_user,public.project_team_id(pid));
ELSE BEGIN pid:=prefix::uuid;EXCEPTION WHEN OTHERS THEN RETURN false;END;RETURN public.is_project_reader(_user,pid) OR public.is_team_project_manager(_user,public.project_team_id(pid));END IF;END $$;
CREATE OR REPLACE FUNCTION public.admin_beta_usage() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Not authorised';END IF;RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'beta_joined_at',t.beta_joined_at,'founding_member',t.founding_member,'projects',(SELECT count(*) FROM public.projects WHERE team_id=t.id),'members',(SELECT count(*) FROM public.team_members WHERE team_id=t.id),'exports',(SELECT count(*) FROM public.project_exports e JOIN public.projects p ON p.id=e.project_id WHERE p.team_id=t.id AND e.status='ready'),'activity',(SELECT coalesce(jsonb_agg(jsonb_build_object('project_id',p.id,'geo_lat',p.geo_lat,'geo_lng',p.geo_lng,'captured_at',ph.captured_at,'created_at',ph.created_at)),'[]'::jsonb) FROM public.photos ph JOIN public.projects p ON p.id=ph.project_id WHERE p.team_id=t.id AND NOT ph.is_reference)) ORDER BY t.created_at DESC),'[]'::jsonb) FROM public.teams t);END $$;
REVOKE ALL ON FUNCTION public.admin_beta_usage() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_beta_usage() TO authenticated,service_role;